:repeat(2,1fr)}}@media(max-width:700px){.container{width:min(calc(100% - 28px),var(--max))}.nav{width:calc(100% - 18px);top:9px}.nav-cta{display:none}.hero{padding-top:100px}.hero h1{font-size:48px}.lead{font-size:14px}.hero-stage{min-height:460px}.portrait-wrap{width:78%}.float{padding:10px}.f1{right:0}.f2{left:0}.f3{right:0}.stats{grid-template-columns:1fr 1fr;margin-bottom:40px}.stats div{border-bottom:1px solid var(--line)}.section{padding:70px 0}.section-head{display:block}.section-head h2{margin:13px 0}.section-head p{margin-top:15px}.bento,.research-layout{grid-template-columns:1fr}.projects-grid{grid-template-columns:1fr}.pub-grid{grid-template-columns:1fr}.cert-grid{grid-template-columns:1fr 1fr}.cert-tools{display:block}.filters{margin-top:10px}.resume-actions{flex-direction:column}.venture{padding:32px}.contact h2{font-size:48px}.footer{display:block}.footer span{display:block;margin:5px 0}.cursor{display:none}}@media(max-width:430px){.cert-grid{grid-template-columns:1fr}.stats b{font-size:26px}.hero h1{font-size:43px}.domain-grid{grid-template-columns:1fr}.actions .btn{width:100%}}
