function renderProjects(cat='all'){const grid=$('#projectsGrid');const list=cat==='all'?projects:projects.filter(p=>p[0]===cat);$('#projectCount').textContent=`${list.length} systems`;grid.innerHTML=list.map((p,i)=>`<article class="project reveal"><span class="num">${String(i+1).padStart(2,'0')}</span><span class="cat">${p[1]}</span><h3>${p[2]}</h3><p>${p[3]}</p><div class="project-tags">${p[4].map(t=>`<span>${t}</span>`).join('')}</div></article>`).join('');animateReveals()}
