let certFilter='all',certQuery='';function renderCerts(){const q=certQuery.toLowerCase();const list=certs.filter(c=>(certFilter==='all'||c[2]===certFilter)&&(!q||c[0].toLowerCase().includes(q)||c[1].toLowerCase().includes(q)));$('#certGrid').innerHTML=list.map(c=>`<article class="cert reveal"><small>${c[2]}</small><h3>${c[0]}</h3><p>${c[1]}</p><a href="${encodeURI(c[3])}" target="_blank" rel="noopener">Open original credential ↗</a></article>`).join('')||'<p style="color:#8f99aa">No matching credentials.</p>';animateReveals()}
const domainData={ai:['AI / ML','Learning systems across applied machine learning and intelligent decision workflows.'],vision:['Computer Vision','YOLO / YOLOv8 detection work spanning person, helmet and licence detection.'],iot:['IoT','Connected sensing, dashboards, MQTT and embedded monitoring systems.'],agri:['Smart Agriculture','Hydroponics, nutrition monitoring and AI-assisted agricultural systems.'],robotics:['ROS / Robotics','ROS / ROS2 learning, assistive robotics and autonomous-system directions.'],medical:['Medical AI','CNN and U-Net directions for medical image analysis and segmentation.']};
function init(){renderProjects();renderTimeline();renderPubs();renderCerts();$$('.project-filter').forEach(b=>b.onclick=()=>{$$('.project-filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderProjects(b.dataset.cat)});$$('.filter').forEach(b=>b.onclick=()=>{$$('.filter').forEach(x=>x.classList.remove('active'));b.classList.add('active');certFilter=b.dataset.filter;renderCerts()});$('#certSearch').oninput=e=>{certQuery=e.target.value;renderCerts()};$$('.domain').forEach(b=>b.onclick=()=>{$$('.domain').forEach(x=>x.classList.remove('active'));b.classList.add('active');const d=domainData[b.dataset.domain];$('#researchTitle').textContent=d[0];$('#researchText').textContent=d[1]});$('.menu').onclick=()=>$('.nav').classList.toggle('mobile-open');$$('.nav nav a').forEach(a=>a.onclick=()=>$('.nav').classList.remove('mobile-open'));initCursor();initProgress();initMotion();initThree()}
function animateReveals(){if(window.gsap&&window.ScrollTrigger){gsap.utils.toArray('.reveal').forEach(el=>{if(el.dataset.revealed)return;el.dataset.revealed='1';gsap.to(el,{opacity:1,y:0,duration:.8,ease:'power3.out',scrollTrigger:{trigger:el,start:'top 88%',once:true}})})}else $$('.reveal').forEach(e=>{e.style.opacity=1;e.style.transform='none'})}
function initMotion(){if(!window.gsap||!window.ScrollTrigger)return;gsap.registerPlugin(ScrollTrigger);animateReveals();gsap.to('.progress',{width:'100%',ease:'none',scrollTrigger:{start:0,end:'max',scrub:.15}});gsap.to('.hero-copy',{y:-45,scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true}});gsap.to('.hero-stage',{y:35,scrollTrigger:{trigger:'.hero',start:'top top',end:'bottom top',scrub:true}})}
function initCursor(){const c=$('.cursor');if(matchMedia('(pointer:coarse)').matches)return;addEventListener('pointermove',e=>{c.style.left=e.clientX+'px';c.style.top=e.clientY+'px'});$$('a,button,.project,.cert').forEach(el=>{el.addEventListener('mouseenter',()=>{c.style.width='34px';c.style.height='34px';c.style.background='rgba(124,245,208,.08)'});el.addEventListener('mouseleave',()=>{c.style.width='18px';c.style.height='18px';c.style.background='transparent'})})}
function initProgress(){addEventListener('scroll',()=>{const h=document.documentElement.scrollHeight-innerHeight;$('.progress').style.width=(scrollY/h*100)+'%'},{passive:true})}
function initThree(){if(!window.THREE||matchMedia('(prefers-reduced-motion:reduce)').matches)return;const canvas=$('#bg');try{const scene=new THREE.Scene(),camera=new THREE.PerspectiveCamera(55,innerWidth/innerHeight,.1,100);camera.position.z=7;const renderer=new THREE.WebGLRenderer({canvas,alpha:true,antialias:true,powerPreference:'high-performance'});renderer.setPixelRatio(Math.min(devicePixelRatio,1.35));renderer.setSize(innerWidth,innerHeight);const n=700,pos=new Float32Array(n*3);for(let i=0;i<n;i++){const r=8*Math.cbrt(Math.random()),a=Math.random()*Math.PI*2,z=(Math.random()-.5)*7;pos[i*3]=Math.cos(a)*r;pos[i*3+1]=Math.sin(a)*r*.55;pos[i*3+2]=z}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.BufferAttribute(pos,3));const m=new THREE.PointsMaterial({color:0x7cf5d0,size:.018,transparent:true,opacity:.52});const pts=new THREE.Points(g,m);scene.add(pts);let tx=0,ty=0;addEventListener('pointermove',e=>{tx=(e.clientX/innerWidth-.5)*.4;ty=(e.clientY/innerHeight-.5)*.2},{passive:true});function tick(){pts.rotation.y+=.00035;pts.rotation.x+=(ty-pts.rotation.x)*.008;pts.rotation.y+=(tx-pts.rotation.y)*.008;renderer.render(scene,camera);requestAnimationFrame(tick)}tick();addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setPixelRatio(Math.min(devicePixelRatio,1.35));renderer.setSize(innerWidth,innerHeight)})}catch(e){canvas.remove()}}
if(document.readyState==='loading')addEventListener('DOMContentLoaded',init);else init();
